def set_age(person, age):
    if age < 0:
        raise ValueError("Age cannot be negative")
    person["age"] = age
    return person

def total(values):
    t = 0
    for v in values:
        if v is not None:
            t += v
    return t

def withdraw(self, amount):
    if self.balance - amount < 0:
        return False
    else:
        self.balance -= amount
        return True

from catalog import get_price

def label(sku):
    return f"{sku}: ${get_price(sku):.2f}"

def apply_code(total_paise, code):
    """Return the total after applying a discount code."""
    if code in config.discount_codes:
        total_paise -= total_paise * config.discount_codes[code]
    return total_paise

from users import find_user

def display_name(users, email):
    user = find_user(users, email)
    if user:
        return user["name"]
    else:
        return 'unknown user'
